import { FC, useCallback, useMemo, useRef, useState } from 'react';

import { Cover } from 'components';
import { useLastDataRefresh } from 'contexts';
import { useDataRefreshForTab } from 'contexts/DataRefreshModal/useDataRefreshForTab';
import { FilterRegistry } from 'domain/Filter';
import { useExportPdf, usePageIndexes } from 'hooks';
import { PDF_DEFAULT_CONFIG } from 'pages/pillars/ValueCreation/VolumePages/constants/pdfConfig';
import {
  useIsAnyLoading,
  useRegisterLoading,
  useVolumePagesKpi,
} from 'pages/pillars/ValueCreation/VolumePages/contexts';
import { useVolumePageExportScopeName } from 'pages/pillars/ValueCreation/VolumePages/hooks/useVolumePageExportScopeName';
import {
  COUNTRIES,
  keyMarketsExportPageSections,
  pageSections,
} from 'pages/pillars/ValueCreation/VolumePages/tabs/Global/constants';
import { CountrySlideWrapper } from 'pages/pillars/ValueCreation/VolumePages/tabs/KeyMarkets/components/CountrySlideWrapper';
import { KeyMarketsProps } from 'pages/pillars/ValueCreation/VolumePages/tabs/KeyMarkets/types';
import {
  StyledExportButton,
  StyledExportIcon,
  StyledExportPageContent,
  StyledExportPageHeader,
  StyledExportPageSection,
} from 'shared/Styles/exportPages.styles';

import { KPI_CONFIGS } from '../../config';

const ExportIcon: FC = () => <StyledExportIcon />;

export const KeyMarkets: FC<KeyMarketsProps> = ({ dataTestId }) => {
  useDataRefreshForTab('volume-page-key-markets');
  const { kpi, kpiName } = useVolumePagesKpi();
  const productScopeName = useVolumePageExportScopeName();
  const containerRef = useRef<HTMLDivElement>(null);
  const { getPageByName } = usePageIndexes(containerRef);
  const { lastDataRefreshKpisDate, lastDataRefreshKpisDateMonthYear } =
    useLastDataRefresh();

  const refreshKpiGroup = useMemo(() => KPI_CONFIGS[kpi].kpiGroup, [kpi]);

  const [isExporting, setIsExporting] = useState(false);
  useRegisterLoading('key-markets-export', isExporting);
  const isAnyLoading = useIsAnyLoading();

  const eurSubFilters = useMemo(() => {
    const dt_end = lastDataRefreshKpisDateMonthYear?.[refreshKpiGroup];

    if (!dt_end) return COUNTRIES.EUR.subFilters;

    return {
      ...COUNTRIES.EUR.subFilters,
      bigNumbers: { country: 'ABI', zone: 'EUR', dt_end, kpi },
      kpi,
    };
  }, [lastDataRefreshKpisDateMonthYear, refreshKpiGroup, kpi]);

  const monthYear = useMemo(() => {
    const date = lastDataRefreshKpisDate[refreshKpiGroup];
    if (!date) return '';

    return new Intl.DateTimeFormat('en-US', {
      month: 'short',
      year: 'numeric',
    }).format(date);
  }, [lastDataRefreshKpisDate, refreshKpiGroup]);

  const period = useMemo(() => {
    const [month, year] = monthYear.toUpperCase().split(' ');

    if (!month || !year) return '';

    return `${month}'${year.slice(-2)}`;
  }, [monthYear]);

  const fileName = useMemo(() => {
    const baseFileName = `Value Creation - Key Markets ${kpiName} - ${monthYear.toUpperCase()}`;

    return `Volume Page - ${productScopeName} - ${baseFileName}`;
  }, [kpiName, monthYear, productScopeName]);

  const { onExport } = useExportPdf(
    useMemo(
      () => ({
        ...PDF_DEFAULT_CONFIG,
        filename: fileName,
      }),
      [fileName],
    ),
  );

  const handlePDFExport = useCallback(async () => {
    setIsExporting(true);

    await onExport(
      keyMarketsExportPageSections
        .map((section) => document.querySelector(`[data-page-name=${section}]`))
        .filter(Boolean) as HTMLElement[],
    );

    setIsExporting(false);
  }, [onExport]);

  return (
    <div
      data-testid={
        dataTestId ? `tabpanel-key-markets-${dataTestId}` : undefined
      }
      ref={containerRef}
    >
      <StyledExportPageContent
        data-testid={
          dataTestId
            ? `tabpanel-key-markets-export-page-content-${dataTestId}`
            : undefined
        }
      >
        <StyledExportPageHeader
          data-testid={
            dataTestId
              ? `tabpanel-key-markets-export-page-header-${dataTestId}`
              : undefined
          }
        >
          <StyledExportButton
            data-testid={
              dataTestId
                ? `tabpanel-key-markets-export-button-${dataTestId}`
                : undefined
            }
            variant="primary"
            size="medium"
            onClick={handlePDFExport}
            isLoading={isAnyLoading}
            icon={ExportIcon}
            trailing
          >
            Export File
          </StyledExportButton>
        </StyledExportPageHeader>

        <StyledExportPageSection
          data-page-name={pageSections.mustWinMarketsCover}
          data-testid={
            dataTestId
              ? `tabpanel-key-markets-export-page-section-${dataTestId}`
              : undefined
          }
        >
          <Cover
            category="One Way Reports"
            name="Key Markets"
            loading={false}
            showLogo
            centerLogo
            centerText
            showLink={false}
            dataTestId={
              dataTestId ? `${dataTestId}-key-markets-cover` : undefined
            }
          />
        </StyledExportPageSection>

        {Object.entries(COUNTRIES).map(([countryCode, config]) => {
          const subFilters =
            countryCode === 'EUR' ? eurSubFilters : config.subFilters;
          return (
            <CountrySlideWrapper
              key={countryCode}
              countryCode={countryCode}
              config={config}
              subFilters={{ ...subFilters, kpi }}
              period={period}
              getPageByName={getPageByName}
              dataTestId={dataTestId}
            />
          );
        })}

        <StyledExportPageSection
          data-page-name={pageSections.backCover}
          data-testid={
            dataTestId
              ? `tabpanel-key-markets-export-page-section-back-cover-${dataTestId}`
              : undefined
          }
        >
          <Cover
            name="Thank You"
            centerLogo
            showLogo
            link={`/value-creation?${FilterRegistry.buildFilterQueryString({
              zone: 'ABI',
              country: 'ABI',
            })}`}
            dataTestId={dataTestId ? `${dataTestId}-thank-you` : undefined}
          />
        </StyledExportPageSection>
      </StyledExportPageContent>
    </div>
  );
};
